type stack []int

func (s *stack) pop() (int, error) {
	if len(*s) == 0 {
		return 0, errors.New("empty stack")
	}
	v := (*s)[len(*s)-1]
	*s = (*s)[:len(*s)-1]
	return v, nil
}

func (s *stack) push(v int) { *s = append(*s, v) }

type op func(s *stack) error

var builtins = map[string]op{
	"+": func(s *stack) error {
		b, err := s.pop()
		if err != nil { return err }
